import {
    Module 
} from "@nestjs/common"
import {
    ConfigModule 
} from "@modules/platform/config/identity"
import {
    PostgresqlPrimaryModule 
} from "@modules/platform/databases/postgresql/identity"
import {
    RedisPrimaryModule 
} from "@modules/platform/caches/redis/primary"
import {
    AccountModule 
} from "@modules/bussiness/account"
import {
    SessionModule 
} from "@modules/bussiness/session"
import {
    OrderModule 
} from "@modules/integrations/order"
import {
    IdentityModule 
} from "@features/identity/identity.module"

/**
 * Composition only, in nivo's monorepo shape: each deployable under apps/<service> has its own root
 * module, and this one wires the identity service - the platform modules (config, the shared Postgres
 * for persons, Redis for sessions), the capability modules (account, session), the HTTP client that
 * consumes contract.checkout.order-for-identity (integrations/order), and the feature that exposes
 * the transport (features/identity). ConfigModule is @Global so TypeOrmModule.forRootAsync and the
 * Redis client can inject AppConfigService without re-importing it.
 */
@Module({
    imports: [
        ConfigModule,
        PostgresqlPrimaryModule,
        RedisPrimaryModule,
        AccountModule,
        SessionModule,
        OrderModule,
        IdentityModule,
    ],
})
export class AppModule {}

import {
    Module 
} from "@nestjs/common"
import {
    ConfigModule 
} from "@modules/platform/config/order"
import {
    PostgresqlPrimaryModule 
} from "@modules/platform/databases/postgresql/order"
import {
    CatalogModule 
} from "@modules/bussiness/catalog"
import {
    CartModule 
} from "@modules/bussiness/cart"
import {
    OrderModule 
} from "@modules/bussiness/order"
import {
    PaymentModule 
} from "@modules/bussiness/payment"
import {
    IdentityModule 
} from "@modules/integrations/identity"
import {
    CheckoutModule 
} from "@features/checkout/checkout.module"

/**
 * Composition only, in nivo's monorepo shape (sibling of apps/identity): the order service's root
 * module wires the platform database, the four capability modules (catalog, cart, order, payment),
 * the HTTP client that verifies sessions against the identity service (the consumer half of the
 * order<->identity pair) and the checkout feature's transport.
 */
@Module({
    imports: [
        ConfigModule,
        PostgresqlPrimaryModule,
        CatalogModule,
        CartModule,
        IdentityModule,
        PaymentModule,
        OrderModule,
        CheckoutModule,
    ],
})
export class AppModule {}

import {
    Module 
} from "@nestjs/common"
import {
    CartModule 
} from "@modules/bussiness/cart"
import {
    CatalogModule 
} from "@modules/bussiness/catalog"
import {
    OrderModule 
} from "@modules/bussiness/order"
import {
    PaymentModule 
} from "@modules/bussiness/payment"
import {
    IdentityModule 
} from "@modules/integrations/identity"
import {
    PostgresqlPrimaryModule 
} from "@modules/platform/databases/postgresql/order"
import {
    CartController 
} from "./transport/http/cart.controller"
import {
    OrderController 
} from "./transport/http/order.controller"
import {
    BuyerController 
} from "./transport/http/buyer.controller"
import {
    HealthController 
} from "./transport/http/health.controller"
import {
    SessionGuard 
} from "./transport/http/session.guard"

/**
 * The checkout feature of apps/order: the HTTP transport for cart, confirmation and the buyer
 * surface, with the session guard in front of every person-scoped door. Capability modules own
 * the behavior; this module only wires.
 */
@Module({
    imports: [
        PostgresqlPrimaryModule,
        CatalogModule,
        CartModule,
        IdentityModule,
        PaymentModule,
        OrderModule,
    ],
    controllers: [CartController,
        OrderController,
        BuyerController,
        HealthController],
    providers: [SessionGuard],
})
export class CheckoutModule {}

import {
    Controller, Get, Param 
} from "@nestjs/common"
import {
    BuyerStatusResult, OrderService 
} from "@modules/bussiness/order"

/**
 * The provider half of contract.checkout.order-for-identity (the layout's cross-repo
 * contract.checkout.order-for-identity surface): GET /buyers/:personId answers whether that
 * person has confirmed orders - the one question the identity service asks this one, live, with
 * no shared database between the two services. An unknown person is not a 404 here: no orders
 * is the honest answer, and the consumer never reads this door for "who is this person".
 */
@Controller("buyers")
export class BuyerController {
    constructor(private readonly orders: OrderService) {}

  @Get(":personId")
    async status(@Param("personId") personId: string): Promise<BuyerStatusResult> {
        return this.orders.buyerStatus(personId)
    }
}

import {
    Test 
} from "@nestjs/testing"
import {
    HttpException, HttpStatus 
} from "@nestjs/common"
import {
    Request 
} from "express"
import {
    CartService 
} from "@modules/bussiness/cart"
import {
    CatalogService 
} from "@modules/bussiness/catalog"
import {
    IdentityApiClient 
} from "@modules/integrations/identity"
import {
    ActorParams 
} from "./session.guard"
import {
    CartController 
} from "./cart.controller"

describe("CartController - the person-scoped cart door",
    () => {
        const cartService = {
            list: jest.fn(), add: jest.fn(), clear: jest.fn() 
        }
        const catalogService = {
            list: jest.fn() 
        }
        let controller: CartController

        beforeEach(async () => {
            jest.clearAllMocks()
            const moduleRef = await Test.createTestingModule({
                providers: [
                    CartController,
                    {
                        provide: CartService, useValue: cartService 
                    },
                    {
                        provide: CatalogService, useValue: catalogService 
                    },
                    // The class-level @UseGuards binding instantiates the guard through DI; its own suite is session.guard.spec.ts.
                    {
                        provide: IdentityApiClient, useValue: {
                            verifySession: jest.fn() 
                        } 
                    },
                ],
            }).compile()
            controller = moduleRef.get(CartController)
        })

        const requestFor = (personId?: string): Request & { actor?: ActorParams } =>
    ({
        actor: personId ? {
            personId 
        } : undefined 
    }) as Request & { actor?: ActorParams }

        it("list answers the actor's items alongside the catalog for rendering",
            async () => {
                cartService.list.mockResolvedValue([{
                    productId: "sku-mug", quantity: 2 
                }])
                catalogService.list.mockResolvedValue([{
                    id: "sku-mug", name: "Mug", priceMinorUnits: 1299, stock: 40 
                }])

                const result = await controller.list(requestFor("person-1"))

                expect(cartService.list).toHaveBeenCalledWith("person-1")
                expect(result).toEqual({
                    items: [{
                        productId: "sku-mug", quantity: 2 
                    }],
                    catalog: [{
                        id: "sku-mug", name: "Mug", priceMinorUnits: 1299, stock: 40 
                    }],
                })
            })

        it("add with a product id and a positive integer quantity reaches the service",
            async () => {
                cartService.add.mockResolvedValue({
                    productId: "sku-mug", quantity: 3 
                })
                const result = await controller.add(requestFor("person-1"),
                    {
                        productId: "sku-mug", quantity: 3 
                    })
                expect(cartService.add).toHaveBeenCalledWith("person-1",
                    "sku-mug",
                    3)
                expect(result).toEqual({
                    item: {
                        productId: "sku-mug", quantity: 3 
                    } 
                })
            })

        it.each([
            [{
                quantity: 2 
            },
            "missing productId"],
            [{
                productId: 42, quantity: 2 
            },
            "non-string productId"],
            [{
                productId: "", quantity: 2 
            },
            "empty productId"],
            [{
                productId: "sku-mug" 
            },
            "missing quantity"],
            [{
                productId: "sku-mug", quantity: 0 
            },
            "zero quantity"],
            [{
                productId: "sku-mug", quantity: -1 
            },
            "negative quantity"],
            [{
                productId: "sku-mug", quantity: 1.5 
            },
            "non-integer quantity"],
            [{
                productId: "sku-mug", quantity: "2" 
            },
            "string quantity"],
        ])("add with %s (%s) refuses 400 REQUEST_INVALID without touching the cart",
            async (body, _label) => {
                try {
                    await controller.add(requestFor("person-1"),
                        body)
                    throw new Error("the call should have failed")
                } catch (error) {
                    expect(error).toBeInstanceOf(HttpException)
                    expect((error as HttpException).getStatus()).toBe(HttpStatus.BAD_REQUEST)
                    expect((error as HttpException).getResponse()).toMatchObject({
                        code: "REQUEST_INVALID" 
                    })
                }
                expect(cartService.add).not.toHaveBeenCalled()
            })

        it("a guarded request carrying no actor is this service's own 401",
            async () => {
                await expect(controller.list(requestFor())).rejects.toMatchObject({
                    status: HttpStatus.UNAUTHORIZED,
                    response: expect.objectContaining({
                        code: "SESSION_INVALID" 
                    }),
                })
                expect(cartService.list).not.toHaveBeenCalled()
            })

        it("clear empties the actor's cart",
            async () => {
                expect(await controller.clear(requestFor("person-1"))).toEqual({
                    cleared: true 
                })
                expect(cartService.clear).toHaveBeenCalledWith("person-1")
            })
    })

import {
    Body, Controller, Delete, Get, HttpException, HttpStatus, Post, Req, UseGuards 
} from "@nestjs/common"
import {
    Request 
} from "express"
import {
    ActorParams, SessionGuard 
} from "./session.guard"
import {
    CartLineResult, CartService 
} from "@modules/bussiness/cart"
import {
    ProductResult, CatalogService 
} from "@modules/bussiness/catalog"

export interface AddCartItemParams {
  productId?: unknown;
  quantity?: unknown;
}

@Controller("cart")
@UseGuards(SessionGuard)
export class CartController {
    constructor(
    private readonly cart: CartService,
    private readonly catalog: CatalogService,
    ) {}

  @Get()
    async list(@Req() request: Request & { actor?: ActorParams }): Promise<{ items: Array<CartLineResult>; catalog: Array<ProductResult> }> {
        const personId = this.person(request)
        return {
            items: await this.cart.list(personId), catalog: await this.catalog.list() 
        }
    }

  @Post("items")
  async add(
    @Req() request: Request & { actor?: ActorParams },
    @Body() body: AddCartItemParams,
  ): Promise<{ item: CartLineResult }> {
      const personId = this.person(request)
      const productId = typeof body?.productId === "string" ? body.productId : ""
      const quantity = typeof body?.quantity === "number" && Number.isInteger(body.quantity) ? body.quantity : 0
      if (!productId || quantity <= 0) {
          throw new HttpException({
              code: "REQUEST_INVALID", message: "productId and a positive integer quantity are required." 
          },
          HttpStatus.BAD_REQUEST)
      }
      return {
          item: await this.cart.add(personId,
              productId,
              quantity) 
      }
  }

  @Delete()
  async clear(@Req() request: Request & { actor?: ActorParams }): Promise<{ cleared: true }> {
      await this.cart.clear(this.person(request))
      return {
          cleared: true 
      }
  }

  private person(request: Request & { actor?: ActorParams }): string {
      if (!request.actor) {
          throw new HttpException({
              code: "SESSION_INVALID", message: "No actor on a guarded request." 
          },
          HttpStatus.UNAUTHORIZED)
      }
      return request.actor.personId
  }
}

import {
    Test 
} from "@nestjs/testing"
import {
    HttpException, HttpStatus 
} from "@nestjs/common"
import {
    PostgresPrimaryClient 
} from "@modules/platform/databases/postgresql/order"
import {
    IdentityApiClient 
} from "@modules/integrations/identity"
import {
    HealthController 
} from "./health.controller"

describe("HealthController - dependency-gated liveness",
    () => {
        const postgres = {
            ping: jest.fn() 
        }
        const identityApi = {
            isHealthy: jest.fn() 
        }
        let controller: HealthController

        beforeEach(async () => {
            jest.clearAllMocks()
            const moduleRef = await Test.createTestingModule({
                providers: [
                    HealthController,
                    {
                        provide: PostgresPrimaryClient, useValue: postgres 
                    },
                    {
                        provide: IdentityApiClient, useValue: identityApi 
                    },
                ],
            }).compile()
            controller = moduleRef.get(HealthController)
        })

        it("answers ok only when postgres and identity both answer",
            async () => {
                postgres.ping.mockResolvedValue(undefined)
                identityApi.isHealthy.mockResolvedValue(true)
                expect(await controller.check()).toEqual({
                    status: "ok",
                    service: "order",
                    checks: {
                        postgres: "ok", identity: "ok" 
                    },
                })
            })

        it("postgres down answers 503 DEPENDENCY_UNAVAILABLE naming postgres",
            async () => {
                postgres.ping.mockRejectedValue(new Error("connection refused"))
                identityApi.isHealthy.mockResolvedValue(true)
                try {
                    await controller.check()
                    throw new Error("the call should have failed")
                } catch (error) {
                    expect(error).toBeInstanceOf(HttpException)
                    expect((error as HttpException).getStatus()).toBe(HttpStatus.SERVICE_UNAVAILABLE)
                    expect((error as HttpException).getResponse()).toMatchObject({
                        code: "DEPENDENCY_UNAVAILABLE" 
                    })
                }
            })

        it("identity unreachable answers 503 DEPENDENCY_UNAVAILABLE even when postgres is fine",
            async () => {
                postgres.ping.mockResolvedValue(undefined)
                identityApi.isHealthy.mockResolvedValue(false)
                await expect(controller.check()).rejects.toMatchObject({
                    status: HttpStatus.SERVICE_UNAVAILABLE,
                    response: expect.objectContaining({
                        code: "DEPENDENCY_UNAVAILABLE" 
                    }),
                })
            })
    })

import {
    Controller, Get, HttpException, HttpStatus 
} from "@nestjs/common"
import {
    PostgresPrimaryClient 
} from "@modules/platform/databases/postgresql/order"
import {
    IdentityApiClient 
} from "@modules/integrations/identity"

interface HealthResult {
  status: "ok";
  service: "order";
  checks: { postgres: "ok"; identity: "ok" };
}

/** GET /health - answers only when Postgres answers and the identity service's own /health does;
 * the dependency check is a real HTTP call, so this door proves the pair is wired while it is up. */
@Controller("health")
export class HealthController {
    constructor(
    private readonly postgres: PostgresPrimaryClient,
    private readonly identityApi: IdentityApiClient,
    ) {}

  @Get()
    async check(): Promise<HealthResult> {
        const checks: Record<"postgres" | "identity", "ok" | "unreachable"> = {
            postgres: "ok", identity: "ok" 
        }
        try {
            await this.postgres.ping()
        } catch {
            checks.postgres = "unreachable"
        }
        if (!(await this.identityApi.isHealthy())) {
            checks.identity = "unreachable"
        }
        if (checks.postgres !== "ok" || checks.identity !== "ok") {
            throw new HttpException(
                {
                    code: "DEPENDENCY_UNAVAILABLE", message: `Dependency refused: ${JSON.stringify(checks)}` 
                },
                HttpStatus.SERVICE_UNAVAILABLE,
            )
        }
        return {
            status: "ok", service: "order", checks: {
                postgres: "ok", identity: "ok" 
            } 
        }
    }
}

import {
    Test 
} from "@nestjs/testing"
import {
    HttpException, HttpStatus 
} from "@nestjs/common"
import {
    Request 
} from "express"
import {
    OrderService 
} from "@modules/bussiness/order"
import {
    CheckoutRefusalException 
} from "@modules/bussiness/order/checkout-refusal.exception"
import {
    IdentityApiClient 
} from "@modules/integrations/identity"
import {
    ActorParams 
} from "./session.guard"
import {
    OrderController 
} from "./order.controller"

describe("OrderController - sds.checkout.order-flow t-confirm door",
    () => {
        const orderService = {
            place: jest.fn() 
        }
        let controller: OrderController

        beforeEach(async () => {
            jest.clearAllMocks()
            const moduleRef = await Test.createTestingModule({
                providers: [
                    OrderController,
                    {
                        provide: OrderService, useValue: orderService 
                    },
                    // The class-level @UseGuards binding instantiates the guard through DI; its own suite is session.guard.spec.ts.
                    {
                        provide: IdentityApiClient, useValue: {
                            verifySession: jest.fn() 
                        } 
                    },
                ],
            }).compile()
            controller = moduleRef.get(OrderController)
        })

        const requestFor = (personId: string | undefined, headers: Record<string, unknown> = {
        }): Request & { actor?: ActorParams } =>
    ({
        actor: personId ? {
            personId 
        } : undefined, headers 
    }) as unknown as Request & { actor?: ActorParams }

        it("places the order for the verified person when no Idempotency-Key arrives",
            async () => {
                orderService.place.mockResolvedValue({
                    orderId: "order-1", status: "confirmed", totalMinorUnits: 2598, currency: "USD", paymentId: "payment-1", replayed: false 
                })
                const result = await controller.place(requestFor("person-1"))
                expect(orderService.place).toHaveBeenCalledWith("person-1",
                    undefined)
                expect(result.orderId).toBe("order-1")
            })

        it("forwards a trimmed Idempotency-Key header to the service",
            async () => {
                orderService.place.mockResolvedValue({
                    orderId: "order-1", replayed: true 
                })
                await controller.place(requestFor("person-1",
                    {
                        "idempotency-key": "  key-1  " 
                    }))
                expect(orderService.place).toHaveBeenCalledWith("person-1",
                    "key-1")
            })

        it.each([
            [{
                "idempotency-key": "" 
            },
            "empty header"],
            [{
                "idempotency-key": "   " 
            },
            "whitespace-only header"],
            [{
                "idempotency-key": ["a",
                    "b"] 
            },
            "multi-valued header"],
        ])("treats %s (%s) as no key at all",
            async (headers, _label) => {
                orderService.place.mockResolvedValue({
                    orderId: "order-1" 
                })
                await controller.place(requestFor("person-1",
                    headers))
                expect(orderService.place).toHaveBeenCalledWith("person-1",
                    undefined)
            })

        it("a guarded request carrying no actor is this service's own 401",
            async () => {
                await expect(controller.place(requestFor(undefined))).rejects.toMatchObject({
                    status: HttpStatus.UNAUTHORIZED,
                    response: expect.objectContaining({
                        code: "SESSION_INVALID" 
                    }),
                })
                expect(orderService.place).not.toHaveBeenCalled()
            })

        it("a named checkout refusal from the service reaches the caller as the refusal, not an empty order",
            async () => {
                orderService.place.mockRejectedValue(
                    new CheckoutRefusalException({
                        ok: false, reason: "insufficient-stock", productId: "sku-thermos", requested: 5, available: 2 
                    }),
                )
                try {
                    await controller.place(requestFor("person-1"))
                    throw new Error("the call should have failed")
                } catch (error) {
                    expect(error).toBeInstanceOf(HttpException)
                    expect((error as HttpException).getStatus()).toBe(HttpStatus.CONFLICT)
                    expect((error as HttpException).getResponse()).toMatchObject({
                        code: "CHECKOUT_REFUSED", reason: "insufficient-stock" 
                    })
                }
            })
    })

import {
    Controller, HttpException, HttpStatus, Post, Req, UseGuards 
} from "@nestjs/common"
import {
    Request 
} from "express"
import {
    ActorParams, SessionGuard 
} from "./session.guard"
import {
    PlaceOrderResult, OrderService 
} from "@modules/bussiness/order"

@Controller("orders")
@UseGuards(SessionGuard)
export class OrderController {
    constructor(private readonly orders: OrderService) {}

  /**
   * POST /orders - the confirmation (sds.checkout.order-flow t-confirm): the session was already
   * verified by the guard (order -> identity over HTTP); this door turns the verified person's
   * cart into a confirmed order or a named refusal, and an Idempotency-Key replay returns the
   * first answer rather than a second order.
   */
  @Post()
    async place(@Req() request: Request & { actor?: ActorParams }): Promise<PlaceOrderResult> {
        if (!request.actor) {
            throw new HttpException({
                code: "SESSION_INVALID", message: "No actor on a guarded request." 
            },
            HttpStatus.UNAUTHORIZED)
        }
        const header = request.headers["idempotency-key"]
        const idempotencyKey = typeof header === "string" && header.trim() ? header.trim() : undefined
        return this.orders.place(request.actor.personId,
            idempotencyKey)
    }
}

import {
    Test 
} from "@nestjs/testing"
import {
    ExecutionContext, HttpException, HttpStatus 
} from "@nestjs/common"
import {
    Request 
} from "express"
import {
    IdentityApiClient 
} from "@modules/integrations/identity"
import {
    ActorParams, SessionGuard 
} from "./session.guard"

describe("SessionGuard - order -> identity verify-session in front of every door",
    () => {
        const identityApi = {
            verifySession: jest.fn() 
        }
        let guard: SessionGuard

        beforeEach(async () => {
            jest.clearAllMocks()
            const moduleRef = await Test.createTestingModule({
                providers: [SessionGuard,
                    {
                        provide: IdentityApiClient, useValue: identityApi 
                    }],
            }).compile()
            guard = moduleRef.get(SessionGuard)
        })

        const contextFor = (headers: Record<string, unknown>) => {
            const request = {
                headers 
            } as unknown as Request & { actor?: ActorParams }
            const context = {
                switchToHttp: () => ({
                    getRequest: () => request 
                }) 
            } as ExecutionContext
            return {
                context, request 
            }
        }

        it("a verified bearer token admits the request carrying the person identity named",
            async () => {
                identityApi.verifySession.mockResolvedValue({
                    personId: "person-1" 
                })
                const { context, request } = contextFor({
                    authorization: "Bearer live-token" 
                })

                expect(await guard.canActivate(context)).toBe(true)
                expect(identityApi.verifySession).toHaveBeenCalledWith("live-token")
                expect(request.actor).toEqual({
                    personId: "person-1" 
                })
            })

        it.each([
            [{
            },
            "no authorization header"],
            [{
                authorization: "Basic dTpw" 
            },
            "non-Bearer scheme"],
            [{
                authorization: "Bearer " 
            },
            "empty bearer token"],
            [{
                authorization: "Bearer    " 
            },
            "whitespace-only bearer token"],
        ])("a request with %s (%s) is this service's own 401 without calling identity",
            async (headers, _label) => {
                const { context } = contextFor(headers)
                try {
                    await guard.canActivate(context)
                    throw new Error("the call should have failed")
                } catch (error) {
                    expect(error).toBeInstanceOf(HttpException)
                    expect((error as HttpException).getStatus()).toBe(HttpStatus.UNAUTHORIZED)
                    expect((error as HttpException).getResponse()).toMatchObject({
                        code: "SESSION_INVALID" 
                    })
                }
                expect(identityApi.verifySession).not.toHaveBeenCalled()
            })

        it("a token identity refuses is this service's own 401, never an invented actor",
            async () => {
                identityApi.verifySession.mockResolvedValue(null)
                const { context, request } = contextFor({
                    authorization: "Bearer stale-token" 
                })
                await expect(guard.canActivate(context)).rejects.toMatchObject({
                    status: HttpStatus.UNAUTHORIZED,
                    response: expect.objectContaining({
                        code: "SESSION_INVALID" 
                    }),
                })
                expect(request.actor).toBeUndefined()
            })

        it("an unreachable identity stays the typed 503 the client raised",
            async () => {
                identityApi.verifySession.mockRejectedValue(
                    new HttpException({
                        code: "IDENTITY_SERVICE_UNAVAILABLE" 
                    },
                    HttpStatus.SERVICE_UNAVAILABLE),
                )
                const { context } = contextFor({
                    authorization: "Bearer live-token" 
                })
                await expect(guard.canActivate(context)).rejects.toMatchObject({
                    status: HttpStatus.SERVICE_UNAVAILABLE,
                    response: expect.objectContaining({
                        code: "IDENTITY_SERVICE_UNAVAILABLE" 
                    }),
                })
            })
    })

import {
    CanActivate, ExecutionContext, HttpException, HttpStatus, Injectable 
} from "@nestjs/common"
import {
    Request 
} from "express"
import {
    IdentityApiClient 
} from "@modules/integrations/identity"

export interface ActorParams {
  personId: string;
}

/**
 * Every checkout door runs through here: the bearer session token is verified against the
 * identity service over real HTTP (modules/integrations/identity), and the request only proceeds
 * carrying the person that verification named. An absent or refused token is this service's own
 * 401 (the consumer-obligation doctrine: propagate the refusal, never invent an actor); an
 * unreachable identity stays the 503 it was.
 */
@Injectable()
export class SessionGuard implements CanActivate {
    constructor(private readonly identityApi: IdentityApiClient) {}

    async canActivate(context: ExecutionContext): Promise<boolean> {
        const request = context.switchToHttp().getRequest<Request & { actor?: ActorParams }>()
        const header = request.headers.authorization ?? ""
        const sessionToken = header.startsWith("Bearer ") ? header.slice("Bearer ".length).trim() : ""
        if (!sessionToken) {
            throw new HttpException({
                code: "SESSION_INVALID", message: "A Bearer session token is required." 
            },
            HttpStatus.UNAUTHORIZED)
        }
        const verified = await this.identityApi.verifySession(sessionToken)
        if (!verified) {
            throw new HttpException({
                code: "SESSION_INVALID", message: "No live session answers this token." 
            },
            HttpStatus.UNAUTHORIZED)
        }
        request.actor = {
            personId: verified.personId 
        }
        return true
    }
}

