describe("AccountController - contract.checkout.order-for-identity account view",
    () => {
        let controller: AccountController
        let accounts: { getAccount: jest.Mock }
        let orderApi: { getBuyerStatus: jest.Mock }

        beforeEach(async () => {
            accounts = {
