                    expect((error as HttpException).getResponse()).toEqual({
                        code: "PERSON_UNKNOWN", message: "No person answers this id." 
                    })
                }
                expect(orderApi.getBuyerStatus).not.toHaveBeenCalled()
            })

        it("propagates the order-service 503 unchanged instead of inventing hasOrders: false",
            async () => {
