export interface AccountWithBuyerStatusResult extends AccountResult {
  hasOrders: boolean;
}

/**
 * GET /accounts/:personId - the account view, including how identity learns a person has orders:
 * the buyer status is read live from the order service through contract.checkout.order-for-identity
 * (modules/integrations/order). An unreachable order service answers 503 with a stable code - it
 * never degrades into `hasOrders: false`, which would make an outage look like an answer.
 */
@Controller("accounts")
export class AccountController {
    constructor(
    private readonly accounts: AccountService,
    private readonly orderApi: OrderApiClient,
    ) {}

  @Get(":personId")
    async getAccount(@Param("personId") personId: string): Promise<AccountWithBuyerStatusResult> {
        const account = await this.accounts.getAccount(personId)
        if (!account) {
            throw new HttpException({
                code: "PERSON_UNKNOWN", message: "No person answers this id." 
            },
            HttpStatus.NOT_FOUND)
        }
        const buyer: BuyerStatusResult = await this.orderApi.getBuyerStatus(personId)
        return {
            ...account, hasOrders: buyer.hasOrders 
        }
    }
}

import {
    Controller, Get, HttpException, HttpStatus 
} from "@nestjs/common"
import {
    PostgresPrimaryClient 
} from "@modules/platform/databases/postgresql/identity"
import {
    RedisPrimaryClient 
} from "@modules/platform/caches/redis/primary"

interface HealthResult {
  status: "ok";
  service: "identity";
  checks: { postgres: "ok"; redis: "ok" };
}

/** The plain HTTP /health the infrastructure probe speaks (todo keeps exactly one door too):
 * it answers only when both dependencies answer, and says which one refused when it does not. */
@Controller("health")
export class HealthController {
    constructor(
    private readonly postgres: PostgresPrimaryClient,
    private readonly redis: RedisPrimaryClient,
    ) {}

  @Get()
    async check(): Promise<HealthResult> {
        const checks: Record<"postgres" | "redis", "ok" | "unreachable"> = {
            postgres: "ok", redis: "ok" 
        }
        try {
            await this.postgres.ping()
        } catch {
            checks.postgres = "unreachable"
        }
        try {
            await this.redis.ping()
        } catch {
            checks.redis = "unreachable"
        }
        if (checks.postgres !== "ok" || checks.redis !== "ok") {
            throw new HttpException(
                {
                    code: "DEPENDENCY_UNAVAILABLE", message: `Dependency refused: ${JSON.stringify(checks)}` 
                },
                HttpStatus.SERVICE_UNAVAILABLE,
            )
        }
        return {
            status: "ok", service: "identity", checks: {
                postgres: "ok", redis: "ok" 
            } 
        }
    }
}

import {
    Body, Controller, HttpException, HttpStatus, Post 
} from "@nestjs/common"
import {
    SessionService 
} from "@modules/bussiness/session"

export interface VerifySessionParams {
  sessionToken?: unknown;
}

/**
 * The session surface the order service calls (its integrations/identity client): the bearer
 * token travels in a JSON body on an internal route, and the answer is only ever the person
 * behind a live session - or a typed 401 the consumer propagates as its own refusal.
 */
@Controller("sessions")
export class SessionController {
    constructor(private readonly sessions: SessionService) {}

  @Post("verify")
    async verify(@Body() body: VerifySessionParams): Promise<{ personId: string }> {
        const sessionToken = typeof body?.sessionToken === "string" ? body.sessionToken : ""
        const personId = await this.sessions.verify(sessionToken)
        if (!personId) {
            throw new HttpException({
                code: "SESSION_INVALID", message: "No live session answers this token." 
            },
            HttpStatus.UNAUTHORIZED)
        }
        return {
            personId 
        }
    }

  @Post("revoke")
  async revoke(@Body() body: VerifySessionParams): Promise<{ revoked: true }> {
      const sessionToken = typeof body?.sessionToken === "string" ? body.sessionToken : ""
      if (!sessionToken) {
          throw new HttpException({
              code: "REQUEST_INVALID", message: "sessionToken is required." 
          },
          HttpStatus.BAD_REQUEST)
      }
      await this.sessions.revoke(sessionToken)
      return {
          revoked: true 
      }
  }
}

import {
    Body, Controller, HttpException, HttpStatus, Post 
} from "@nestjs/common"
import {
    AccountService 
} from "@modules/bussiness/account"
import {
    SessionService 
} from "@modules/bussiness/session"

export interface SignInParams {
  email?: unknown;
  password?: unknown;
}

@Controller("auth")
export class SignInController {
    constructor(
    private readonly accounts: AccountService,
    private readonly sessions: SessionService,
    ) {}

  /** The demo signup door - what makes the live proof repeatable: every run registers a fresh
   * visitor instead of reusing the seeded person. A taken address is 409, nothing else. */
  @Post("register")
    async register(@Body() body: SignInParams): Promise<{ personId: string }> {
        const email = typeof body?.email === "string" ? body.email : ""
        const password = typeof body?.password === "string" ? body.password : ""
        if (!email.includes("@") || password.length < 8) {
            throw new HttpException({
                code: "REQUEST_INVALID", message: "A plausible email and a password of at least 8 characters are required." 
            },
            HttpStatus.BAD_REQUEST)
        }
        const personId = await this.accounts.register(email,
            password)
        if (!personId) {
            throw new HttpException({
                code: "EMAIL_TAKEN", message: "An account already answers this email." 
            },
            HttpStatus.CONFLICT)
        }
        return {
            personId 
        }
    }

  /** fr.identity.sign-in: the pair is checked, and exactly one live session answers. A refusal
   * names neither half (br.identity.sign-in) - unknown email and wrong password are the same
   * status and the same body. */
  @Post("sign-in")
  async signIn(@Body() body: SignInParams): Promise<{ sessionToken: string; personId: string }> {
      const email = typeof body?.email === "string" ? body.email : ""
      const password = typeof body?.password === "string" ? body.password : ""
      if (!email || !password) {
          throw new HttpException({
              code: "REQUEST_INVALID", message: "email and password are required." 
          },
          HttpStatus.BAD_REQUEST)
      }
      const personId = await this.accounts.verifyCredentials(email,
          password)
      if (!personId) {
          throw new HttpException({
              code: "INVALID_CREDENTIALS", message: "The email and password pair is not recognized." 
          },
          HttpStatus.UNAUTHORIZED)
      }
      return this.sessions.issue(personId)
  }
}

