import {
    Injectable 
} from "@nestjs/common"
import {
    InjectRepository 
} from "@nestjs/typeorm"
import {
    Repository 
} from "typeorm"
import {
    PersonEntity, POSTGRESQL_PRIMARY 
} from "@modules/platform/databases/postgresql/identity"
import {
    PasswordPolicy 
} from "./password.policy"

export interface AccountResult {
  personId: string;
  email: string;
}

/** br.identity.sign-in: credential checking and the person behind it. Refusals come back as
 * nulls for the caller to turn into its own refusal; no half of the pair is ever named. */
@Injectable()
export class AccountService {
    constructor(
    @InjectRepository(PersonEntity,
        POSTGRESQL_PRIMARY) private readonly people: Repository<PersonEntity>,
    private readonly passwords: PasswordPolicy,
    ) {}

    async verifyCredentials(email: string, password: string): Promise<string | null> {
        const person = await this.people.findOneBy({
            email 
        })
        if (!person) return null
        return this.passwords.verify(password,
            person.passwordHash) ? person.id : null
    }

    /** The signup door: a visitor becomes a person here, and a buyer at checkout confirmation.
   * Returns null for a taken address (the caller answers 409; no timing side channel matters
   * for a public door, but the row is never half-written - one insert or none). */
    async register(email: string, password: string): Promise<string | null> {
        const person = new PersonEntity()
        person.email = email
        person.passwordHash = this.passwords.hash(password)
        try {
            const saved = await this.people.save(person)
            return saved.id
        } catch {
            return null
        }
    }

    async getAccount(personId: string): Promise<AccountResult | null> {
        const person = await this.people.findOneBy({
            id: personId 
        })
        return person ? {
            personId: person.id, email: person.email 
        } : null
    }
}

import {
    Injectable 
} from "@nestjs/common"
import {
    scryptSync, timingSafeEqual 
} from "node:crypto"

/**
 * The demo credential scheme: scrypt with a fixed per-example salt, verified in constant time.
 * A real product delegates passwords to an identity provider (todo's login feature shows that
 * shape with Keycloak); this example keeps the verification local and honest about it being a
 * demo - the seeded hash in the migration is computed with exactly this salt.
 */
export const DEMO_PASSWORD_SALT = "ecommerce-app-demo"

@Injectable()
export class PasswordPolicy {
    hash(plain: string): string {
        return scryptSync(plain,
            DEMO_PASSWORD_SALT,
            64).toString("hex")
    }

    verify(plain: string, storedHashHex: string): boolean {
        const candidate = Buffer.from(scryptSync(plain,
            DEMO_PASSWORD_SALT,
            64).toString("hex"))
        const stored = Buffer.from(storedHashHex)
        if (candidate.length !== stored.length) return false
        return timingSafeEqual(candidate,
            stored)
    }
}

