                expect(options.url).toBe("postgres://spec-host:5432/specdb")
                expect(options.entities).toEqual([
                    ProductEntity,
                    CartItemEntity,
                    OrderEntity,
                    OrderLineEntity,
                    PaymentEntity,
                ])
                expect(String((options.migrations as Array<unknown>)?.[0])).toMatch(/migrations[/\\]\*\.\{js,ts\}$/)
                expect(options.migrationsRun).toBe(true)
                expect(options.synchronize).toBe(false)
                expect(options.retryAttempts).toBe(2)
            })
    })

import {
    Module 
} from "@nestjs/common"
import {
    TypeOrmModule 
} from "@nestjs/typeorm"
import {
    join 
} from "node:path"
import {
    AppConfigService 
} from "../../../config/order"
import {
    POSTGRESQL_PRIMARY 
} from "./constants/connection"
import {
    PostgresPrimaryClient 
} from "./primary.client"
import {
    CartItemEntity, OrderEntity, OrderLineEntity, PaymentEntity, ProductEntity 
} from "./entities"

/**
 * The one platform database module (house shape, see apps/identity's), owning the order service's
 * tables - product, cart_item, sales_order, sales_order_line, payment - in the same dev Postgres
 * database as the identity service's schema (they are disjoint; integration.checkout.postgres).
 */
@Module({
    imports: [
        TypeOrmModule.forRootAsync({
            name: POSTGRESQL_PRIMARY,
            inject: [AppConfigService],
            useFactory: (config: AppConfigService) => ({
                type: "postgres" as const,
                url: config.getDatabaseUrl(),
                entities: [ProductEntity,
                    CartItemEntity,
                    OrderEntity,
                    OrderLineEntity,
                    PaymentEntity],
                migrations: [join(__dirname,
                    "migrations",
                    "*.{js,ts}")],
                migrationsRun: true,
                synchronize: false,
                retryAttempts: 2,
            }),
        }),
    ],
    providers: [PostgresPrimaryClient],
    exports: [PostgresPrimaryClient],
})
export class PostgresqlPrimaryModule {}

import {
    Test, TestingModule 
} from "@nestjs/testing"
import {
    E2EAuthService,
    E2EDbService,
    E2EHttpClient,
    E2EHttpService,
    TestContext,
    TestingInfraModule,
} from "@tests/infra"

jest.setTimeout(120_000)

interface ProductView {
  id: string;
  name: string;
  priceMinorUnits: number;
  stock: number;
}

interface CartView {
  items: Array<{ productId: string; quantity: number }>;
  catalog: Array<ProductView>;
}

interface PlaceOrderView {
  orderId: string;
  status: "confirmed";
  totalMinorUnits: number;
  currency: "USD";
  paymentId: string;
  replayed: boolean;
}

interface CountRow {
  count: number;
}

/**
 * The happy path of sds.checkout.order-flow end to end: a visitor registers on identity, signs
 * in, browses the catalog through the order service's cart door, fills the cart, confirms with
 * an Idempotency-Key (a replay answers the same order, never a second payment), and the
 * confirmation's transaction leaves a captured payment, decremented stock and an empty cart.
 * The Postgres reads are out-of-band verification only - every step of the journey itself
 * travels over the real HTTP doors of both services.
 */
describe("checkout journey (e2e)",
    () => {
        let moduleRef: TestingModule | undefined
        let auth: E2EAuthService
        let db: E2EDbService
        let http: E2EHttpService

        const email = `e2e-checkout-${Date.now()}@starci.test`
        const password = "e2e-checkout-pass"
        let personId = ""

        beforeAll(async () => {
            moduleRef = await Test.createTestingModule({
                imports: [TestingInfraModule.register({
                    context: TestContext.E2E 
                })],
            }).compile()
            // compile() only instantiates; init() runs the onModuleInit hook that brings the stack up.
            await moduleRef.init()
            auth = moduleRef.get(E2EAuthService)
            db = moduleRef.get(E2EDbService)
            http = moduleRef.get(E2EHttpService)
            // The stack counts as up only when both services answer their real dependency-checked /health.
            const identity: E2EHttpClient = http.client("identity")
            const order: E2EHttpClient = http.client("order")
            expect((await identity.get<{ status: string }>("/health")).data.status).toBe("ok")
            expect((await order.get<{ status: string }>("/health")).data.status).toBe("ok")
        })

        afterAll(async () => {
            if (personId) await auth.deleteAccount(personId)
            await moduleRef?.close()
        })

        it("register → browse catalog → add to cart → checkout → pay → order confirmed → cart empty",
            async () => {
                const identity: E2EHttpClient = http.client("identity")

                const registered = await identity.post<{ personId: string }>("/auth/register",
                    {
                        email, password 
                    })
                expect(registered.status).toBe(201)
                expect(registered.data.personId).toEqual(expect.any(String))
                personId = registered.data.personId

                const signedIn = await identity.post<{ sessionToken: string; personId: string }>("/auth/sign-in",
                    {
                        email,
                        password,
                    })
                expect(signedIn.status).toBe(201)
                expect(signedIn.data.personId).toBe(personId)
                const sessionToken = signedIn.data.sessionToken

                const buyer: E2EHttpClient = http.client("order",
                    {
                        bearerToken: sessionToken 
                    })

                // The catalog is read through the cart door - it is the only catalog surface checkout has.
                const browsed = await buyer.get<CartView>("/cart")
                expect(browsed.status).toBe(200)
                expect(browsed.data.items).toEqual([])
                const mug = browsed.data.catalog.find((p) => p.id === "sku-mug")
                const notebook = browsed.data.catalog.find((p) => p.id === "sku-notebook")
                expect(mug).toBeDefined()
                expect(notebook).toBeDefined()
                const expectedTotal = mug!.priceMinorUnits * 2 + notebook!.priceMinorUnits

                const addedMug = await buyer.post("/cart/items",
                    {
                        productId: "sku-mug", quantity: 2 
                    })
                expect(addedMug.status).toBe(201)
                const addedNotebook = await buyer.post("/cart/items",
                    {
                        productId: "sku-notebook", quantity: 1 
                    })
                expect(addedNotebook.status).toBe(201)

                const filled = await buyer.get<CartView>("/cart")
                expect(filled.data.items).toEqual([
                    {
                        productId: "sku-mug", quantity: 2 
                    },
                    {
                        productId: "sku-notebook", quantity: 1 
                    },
                ])

                const idempotencyKey = `e2e-${personId}`
                const placed = await buyer.post<PlaceOrderView>("/orders",
                    undefined,
                    {
                        "idempotency-key": idempotencyKey 
                    })
                expect(placed.status).toBe(201)
                expect(placed.data).toMatchObject({
                    status: "confirmed",
                    totalMinorUnits: expectedTotal,
                    currency: "USD",
                    replayed: false,
                })
                expect(placed.data.orderId).toEqual(expect.any(String))
                expect(placed.data.paymentId).toEqual(expect.any(String))

                // Replay with the same key: the first answer again, not a second order or a second capture.
                const replayed = await buyer.post<PlaceOrderView>("/orders",
                    undefined,
                    {
                        "idempotency-key": idempotencyKey 
                    })
                expect(replayed.status).toBe(201)
                expect(replayed.data.orderId).toBe(placed.data.orderId)
                expect(replayed.data.paymentId).toBe(placed.data.paymentId)
                expect(replayed.data.replayed).toBe(true)

                const emptied = await buyer.get<CartView>("/cart")
                expect(emptied.data.items).toEqual([])

                const orders = await db.query<{ status: string; total_minor_units: number }>(
                    "SELECT status, total_minor_units FROM sales_order WHERE id = $1",
                    [placed.data.orderId],
                )
                expect(orders).toEqual([{
                    status: "confirmed", total_minor_units: expectedTotal 
                }])

                const lines = await db.query<CountRow>(
                    "SELECT COUNT(*)::int AS count FROM sales_order_line WHERE order_id = $1",
                    [placed.data.orderId],
                )
                expect(lines[0].count).toBe(2)

                const payments = await db.query<{ status: string; amount_minor_units: number }>(
                    "SELECT status, amount_minor_units FROM payment WHERE person_id = $1",
                    [personId],
                )
                expect(payments).toEqual([{
                    status: "captured", amount_minor_units: expectedTotal 
                }])

                const cartRows = await db.query<CountRow>(
                    "SELECT COUNT(*)::int AS count FROM cart_item WHERE person_id = $1",
                    [personId],
                )
                expect(cartRows[0].count).toBe(0)

                const mugStock = await db.query<{ stock: number }>("SELECT stock FROM product WHERE id = $1",
                    ["sku-mug"])
                expect(mugStock[0].stock).toBe(mug!.stock - 2)

                // contract.checkout.order-for-identity live: identity's account door reads buyer status from
                // the order service over HTTP - the confirmation is what flipped it.
                const buyerStatus = await http.client("order").get<{ hasOrders: boolean }>(`/buyers/${personId}`)
                expect(buyerStatus.data.hasOrders).toBe(true)
                const account = await identity.get<{ personId: string; email: string; hasOrders: boolean }>(`/accounts/${personId}`)
                expect(account.status).toBe(200)
                expect(account.data).toMatchObject({
                    personId, email, hasOrders: true 
                })

                // Sign-out: the guard consults identity live, so the revoked token stops answering on order.
                const revoked = await identity.post("/sessions/revoke",
                    {
                        sessionToken 
                    })
                expect(revoked.status).toBe(201)
                const afterRevoke = await buyer.get("/cart")
                expect(afterRevoke.status).toBe(401)
            })
    })

import {
    Test, TestingModule 
} from "@nestjs/testing"
import {
    E2EAuthService,
    E2EDbService,
    E2EHttpClient,
    E2EHttpService,
    TestContext,
    TestingInfraModule,
} from "@tests/infra"

jest.setTimeout(120_000)

interface CartView {
  items: Array<{ productId: string; quantity: number }>;
  catalog: Array<{ id: string; name: string; priceMinorUnits: number; stock: number }>;
}

interface RefusalView {
  code: "CHECKOUT_REFUSED";
  reason: "cart-empty" | "unknown-product" | "insufficient-stock";
  productId: string;
  requested?: number;
  available?: number;
}

interface PlaceOrderView {
  orderId: string;
  status: "confirmed";
  totalMinorUnits: number;
  currency: "USD";
  paymentId: string;
  replayed: boolean;
}

interface CountRow {
  count: number;
}

/**
 * The refusal half of sds.checkout.order-flow (t-refuse). The API contract has no external PSP
 * and no pending/declined order state - payment capture runs inside the same transaction as the
 * guarded stock decrement, so the "payment declined" step of the journey is the named refusal
 * (CHECKOUT_REFUSED) and its honest outcome is the full rollback: no order row, no payment row,
 * stock unmoved, cart kept. Retry is a fresh POST /orders once the cart is corrected; cancel is
 * DELETE /cart, after which a confirmation is refused as cart-empty.
 */
describe("payment failure (e2e)",
    () => {
        let moduleRef: TestingModule | undefined
        let auth: E2EAuthService
        let db: E2EDbService
        let http: E2EHttpService

        const password = "e2e-payment-pass"
        const personIds: Array<string> = []

        async function freshBuyer(suffix: string): Promise<{ buyer: E2EHttpClient; personId: string }> {
            const email = `e2e-payment-${suffix}-${Date.now()}@starci.test`
            const { personId } = await auth.register(email,
                password)
            personIds.push(personId)
            const { sessionToken } = await auth.signIn(email,
                password)
            return {
                buyer: http.client("order",
                    {
                        bearerToken: sessionToken 
                    }), personId 
            }
        }

        async function persistedOrderCount(personId: string): Promise<number> {
            const rows = await db.query<CountRow>(
                "SELECT COUNT(*)::int AS count FROM sales_order WHERE person_id = $1",
                [personId],
            )
            return rows[0].count
        }

        async function persistedPaymentCount(personId: string): Promise<number> {
            const rows = await db.query<CountRow>(
                "SELECT COUNT(*)::int AS count FROM payment WHERE person_id = $1",
                [personId],
            )
            return rows[0].count
        }

        beforeAll(async () => {
            moduleRef = await Test.createTestingModule({
                imports: [TestingInfraModule.register({
                    context: TestContext.E2E 
                })],
            }).compile()
            // compile() only instantiates; init() runs the onModuleInit hook that brings the stack up.
            await moduleRef.init()
            auth = moduleRef.get(E2EAuthService)
            db = moduleRef.get(E2EDbService)
            http = moduleRef.get(E2EHttpService)
            expect((await http.client("order").get<{ status: string }>("/health")).data.status).toBe("ok")
        })

        afterAll(async () => {
            if (auth) {
                for (const personId of personIds) await auth.deleteAccount(personId)
            }
            await moduleRef?.close()
        })

        it("a refused confirmation rolls back atomically; the corrected retry captures exactly once",
            async () => {
                const { buyer, personId } = await freshBuyer("retry")

                // sku-thermos seeds at stock 2 on a fresh stack - asking for 3 is a guaranteed refusal.
                const browsed = await buyer.get<CartView>("/cart")
                const thermos = browsed.data.catalog.find((p) => p.id === "sku-thermos")
                expect(thermos).toBeDefined()
                const seededStock = thermos!.stock

                const added = await buyer.post("/cart/items",
                    {
                        productId: "sku-thermos", quantity: seededStock + 1 
                    })
                expect(added.status).toBe(201)

                const idempotencyKey = `e2e-${personId}`
                const refused = await buyer.post<RefusalView>("/orders",
                    undefined,
                    {
                        "idempotency-key": idempotencyKey 
                    })
                expect(refused.status).toBe(409)
                expect(refused.data).toMatchObject({
                    code: "CHECKOUT_REFUSED",
                    reason: "insufficient-stock",
                    productId: "sku-thermos",
                    requested: seededStock + 1,
                    available: seededStock,
                })

                // The rollback: cart kept, nothing persisted, stock unmoved - a refusal never half-writes.
                const cartKept = await buyer.get<CartView>("/cart")
                expect(cartKept.data.items).toEqual([{
                    productId: "sku-thermos", quantity: seededStock + 1 
                }])
                expect(await persistedOrderCount(personId)).toBe(0)
                expect(await persistedPaymentCount(personId)).toBe(0)
                const stockAfter = await db.query<{ stock: number }>("SELECT stock FROM product WHERE id = $1",
                    ["sku-thermos"])
                expect(stockAfter[0].stock).toBe(seededStock)

                // Correct the cart and retry with the same key: this time the confirmation lands.
                await buyer.delete("/cart")
                const corrected = await buyer.post("/cart/items",
                    {
                        productId: "sku-thermos", quantity: seededStock 
                    })
                expect(corrected.status).toBe(201)

                const retried = await buyer.post<PlaceOrderView>("/orders",
                    undefined,
                    {
                        "idempotency-key": idempotencyKey 
                    })
                expect(retried.status).toBe(201)
                expect(retried.data).toMatchObject({
                    status: "confirmed",
                    totalMinorUnits: thermos!.priceMinorUnits * seededStock,
                    currency: "USD",
                    replayed: false,
                })

                const payments = await db.query<{ status: string; amount_minor_units: number }>(
                    "SELECT status, amount_minor_units FROM payment WHERE person_id = $1",
                    [personId],
                )
                expect(payments).toEqual([{
                    status: "captured", amount_minor_units: thermos!.priceMinorUnits * seededStock 
                }])
                expect((await buyer.get<CartView>("/cart")).data.items).toEqual([])
                const stockSoldOut = await db.query<{ stock: number }>("SELECT stock FROM product WHERE id = $1",
                    ["sku-thermos"])
                expect(stockSoldOut[0].stock).toBe(0)
            })

        it("a refused confirmation can be abandoned - clearing the cart leaves no order behind",
            async () => {
                const { buyer, personId } = await freshBuyer("cancel")

                const browsed = await buyer.get<CartView>("/cart")
                const thermos = browsed.data.catalog.find((p) => p.id === "sku-thermos")
                expect(thermos).toBeDefined()

                await buyer.post("/cart/items",
                    {
                        productId: "sku-thermos", quantity: thermos!.stock + 1 
                    })
                const refused = await buyer.post<RefusalView>("/orders")
                expect(refused.status).toBe(409)
                expect(refused.data.reason).toBe("insufficient-stock")

                // Cancel per api contract: the buyer empties the cart and walks away.
                const cleared = await buyer.delete("/cart")
                expect(cleared.status).toBe(200)
                expect((await buyer.get<CartView>("/cart")).data.items).toEqual([])

                // A confirmation with nothing to confirm is the cart-empty refusal, not a silent order.
                const empty = await buyer.post<RefusalView>("/orders")
                expect(empty.status).toBe(400)
                expect(empty.data).toMatchObject({
                    code: "CHECKOUT_REFUSED", reason: "cart-empty" 
                })

                expect(await persistedOrderCount(personId)).toBe(0)
                expect(await persistedPaymentCount(personId)).toBe(0)
                const stockAfter = await db.query<{ stock: number }>("SELECT stock FROM product WHERE id = $1",
                    ["sku-thermos"])
                expect(stockAfter[0].stock).toBe(thermos!.stock)
            })
    })

import {
    Test, TestingModule 
} from "@nestjs/testing"
import {
    E2EAuthService,
    E2EDbService,
    E2EHttpService,
    E2EStackService,
    TestContext,
    TestingInfraModule,
} from "@tests/infra"

/**
 * Exemplar for the e2e contract: fr.identity.sign-in as one complete A->Z journey over the public
 * HTTP doors only - register, refused duplicates and wrong pairs, sign-in, session verify, the
 * account view that itself proves the identity->order hop (hasOrders is read live from the order
 * service), revoke, and out-of-band persistence/cleanup verification.
 *
 * Run: npx jest --config test/e2e/jest.config.js test/e2e/identity/sign-up-sign-in.e2e-spec.ts
 */
describe("identity sign-up → sign-in journey",
    () => {
        let moduleRef: TestingModule
        let stack: E2EStackService
        let http: E2EHttpService
        let db: E2EDbService
        let auth: E2EAuthService

        const email = `e2e-${Date.now()}@ecommerce.dev`
        const password = "e2e-journey-pass-1"

        beforeAll(async () => {
            moduleRef = await Test.createTestingModule({
                imports: [TestingInfraModule.register({
                    context: TestContext.E2E, specId: "identity/sign-up-sign-in" 
                })],
            }).compile()
            // compile() only instantiates providers; init() is what runs onModuleInit (compose up + api boot).
            await moduleRef.init()
            stack = moduleRef.get(E2EStackService)
            http = moduleRef.get(E2EHttpService)
            db = moduleRef.get(E2EDbService)
            auth = moduleRef.get(E2EAuthService)
        },
        300_000)

        afterAll(async () => {
            await moduleRef.close()
            // Teardown verification is part of the contract: this run's containers and volumes must be gone.
            expect(stack.cleanupReport).not.toBeNull()
            expect(stack.cleanupReport?.clean).toBe(true)
        })

        it("registers a person, issues and verifies a session, then revokes it",
            async () => {
                const identity = http.client("identity")

                // Dependency ordering, observed: the stack could only reach this point with postgres+redis
                // healthy and identity's /health answering before order was ever spawned.
                expect(stack.readiness.map((r) => r.label)).toEqual([
                    "postgres:5432",
                    "redis:6379",
                    expect.stringContaining("identity /health"),
                    expect.stringContaining("order /health"),
                ])

                const registered = await identity.post<{ personId: string }>("/auth/register",
                    {
                        email, password 
                    })
                expect(registered.status).toBe(201)
                expect(registered.body.personId).toBeTruthy()
                const personId = registered.body.personId

                const taken = await identity.post<{ code?: string }>("/auth/register",
                    {
                        email, password 
                    })
                expect(taken.status).toBe(409)
                expect(taken.body.code).toBe("EMAIL_TAKEN")

                const wrongPair = await identity.post<{ code?: string; message?: string }>("/auth/sign-in",
                    {
                        email,
                        password: "not-the-password",
                    })
                expect(wrongPair.status).toBe(401)
                expect(wrongPair.body.code).toBe("INVALID_CREDENTIALS")
                // A refusal may name the pair or neither half, but it must not single one out:
                // no "unknown email", no "wrong password".
                expect(wrongPair.body.message ?? "").not.toMatch(/unknown|not found|no such|does ?n['’]?t exist|unregistered|no account/i)
                expect(wrongPair.body.message ?? "").not.toMatch(/(wrong|incorrect|invalid|bad) (password|passphrase)/i)

                const signedIn = await identity.post<{ sessionToken: string; personId: string }>("/auth/sign-in",
                    {
                        email, password 
                    })
                expect(signedIn.status).toBe(201)
                expect(signedIn.body.personId).toBe(personId)
                const { sessionToken } = signedIn.body

                const verified = await identity.post<{ personId: string }>("/sessions/verify",
                    {
                        sessionToken 
                    })
                expect(verified.status).toBe(201)
                expect(verified.body.personId).toBe(personId)

                // The account view is the cross-service proof: identity reads hasOrders live from order's
                // GET /buyers/:personId. A brand-new person is not a buyer yet - a reachable order answers so.
                const account = await identity.get<{ personId: string; email: string; hasOrders: boolean }>(`/accounts/${personId}`)
                expect(account.status).toBe(200)
                expect(account.body).toEqual({
                    personId, email, hasOrders: false 
                })

                // Out-of-band verification: the person really persisted on this run's postgres volume, and
                // both services' migration sets ran on it.
                const rows = await db.query<{ id: string; email: string }>("select id, email from identity_person where id = $1",
                    [personId])
                expect(rows).toEqual([{
                    id: personId, email 
                }])
                const schema = stack.schemaSnapshot()
                expect(schema.tables).toEqual(expect.arrayContaining(["identity_person",
                    "product",
                    "sales_order"]))

                const revoked = await identity.post<{ revoked: boolean }>("/sessions/revoke",
                    {
                        sessionToken 
                    })
                expect(revoked.status).toBe(201)
                expect(revoked.body.revoked).toBe(true)

                const afterRevoke = await identity.post<{ code?: string }>("/sessions/verify",
                    {
                        sessionToken 
                    })
                expect(afterRevoke.status).toBe(401)
                expect(afterRevoke.body.code).toBe("SESSION_INVALID")
            })
    })

import {
    Test, TestingModule 
} from "@nestjs/testing"
import {
    E2EAuthService,
    E2EDbService,
    E2EHttpService,
    E2EStackService,
    retryUntil,
    TestContext,
    TestingInfraModule,
} from "@tests/infra"
import {
    bearer, CartView, PlaceOrderView, RefusalView, registerBuyer 
} from "./lifecycle.helpers"

/**
 * The identity↔order boundary for real: an order-door call authenticates by the guard asking
 * identity's /sessions/verify over live HTTP on EVERY request, so when a session dies
 * mid-journey - revoked on the identity side, or expired by the Redis TTL that owns the session
 * store - the next order call is a 401 SESSION_INVALID, not a cached actor. Re-auth then issues
 * a new token for the same person, and the person-keyed state (the cart) resumes the journey.
 *
 * The expiry journey needs a short session TTL: IDENTITY_SESSION_TTL_SECONDS is the identity
 * app's own config knob, and E2EStackService spawns the api children with {...process.env}, so
 * setting it here before compile() reaches the spawned identity process.
 *
 * Run: npx jest --config test/e2e/jest.config.js test/e2e/order-lifecycle/cross-service-identity.e2e-spec.ts
 */
describe("order lifecycle - identity↔order boundary (e2e)",
    () => {
        let moduleRef: TestingModule
        let stack: E2EStackService
        let auth: E2EAuthService
        let db: E2EDbService
        let http: E2EHttpService

        const password = "e2e-xservice-pass"
        const personIds: Array<string> = []
        const previousTtl = process.env.IDENTITY_SESSION_TTL_SECONDS

        beforeAll(async () => {
            process.env.IDENTITY_SESSION_TTL_SECONDS = "10"
            moduleRef = await Test.createTestingModule({
                imports: [TestingInfraModule.register({
                    context: TestContext.E2E, specId: "order-lifecycle/cross-service-identity" 
                })],
            }).compile()
            // compile() only instantiates; init() runs the onModuleInit hook that brings the stack up.
            await moduleRef.init()
            stack = moduleRef.get(E2EStackService)
            auth = moduleRef.get(E2EAuthService)
            db = moduleRef.get(E2EDbService)
            http = moduleRef.get(E2EHttpService)
        },
        300_000)

        afterAll(async () => {
            for (const personId of personIds) await auth.deleteAccount(personId)
            await moduleRef.close()
            if (previousTtl === undefined) delete process.env.IDENTITY_SESSION_TTL_SECONDS
            else process.env.IDENTITY_SESSION_TTL_SECONDS = previousTtl
            // Teardown verification is part of the contract: this run's containers and volumes are gone.
            expect(stack.cleanupReport).not.toBeNull()
            expect(stack.cleanupReport?.clean).toBe(true)
        })

        it("a revoked session is refused at the order boundary until re-auth resumes the same buyer",
            async () => {
                const identity = http.client("identity")
                const order = http.client("order")
                const buyer = await registerBuyer(auth,
                    "xsrv-a",
                    password)
                personIds.push(buyer.personId)
                const tokenA = bearer(buyer.sessionToken)

                // The token is live at the order boundary - the guard just verified it against identity.
                const added = await order.post("/cart/items",
                    {
                        productId: "sku-notebook", quantity: 1 
                    },
                    tokenA)
                expect(added.status).toBe(201)

                const revoked = await identity.post<{ revoked: boolean }>("/sessions/revoke",
                    {
                        sessionToken: buyer.sessionToken 
                    })
                expect(revoked.status).toBe(201)
                expect(revoked.body.revoked).toBe(true)

                // Identity refuses the dead token, and so does the order boundary: the guard consults
                // identity on every call, so no actor survives the revoke.
                const verifyDead = await identity.post<RefusalView>("/sessions/verify",
                    {
                        sessionToken: buyer.sessionToken 
                    })
                expect(verifyDead.status).toBe(401)
                expect(verifyDead.body.code).toBe("SESSION_INVALID")
                const refused = await order.get<RefusalView>("/cart",
                    tokenA)
                expect(refused.status).toBe(401)
                expect(refused.body.code).toBe("SESSION_INVALID")

                // Re-auth: a different token for the same person.
                const resumed = await auth.signIn(buyer.email,
                    password)
                expect(resumed.personId).toBe(buyer.personId)
                expect(resumed.sessionToken).not.toBe(buyer.sessionToken)
                const tokenB = bearer(resumed.sessionToken)

                // Resume: the cart line added under the dead session is person-keyed, so it is still there...
                const cart = await order.get<CartView>("/cart",
                    tokenB)
                expect(cart.status).toBe(200)
                expect(cart.body.items).toEqual([{
                    productId: "sku-notebook", quantity: 1 
                }])

                // ...and the journey completes under the new session.
                const placed = await order.post<PlaceOrderView>("/orders",
                    undefined,
                    {
                        ...tokenB, "idempotency-key": `${buyer.personId}-resume` 
                    })
                expect(placed.status).toBe(201)
                expect(placed.body.status).toBe("confirmed")

                const orders = await db.query<{ status: string }>("select status from sales_order where person_id = $1",
                    [buyer.personId])
                expect(orders).toEqual([{
                    status: "confirmed" 
                }])
                const account = await identity.get<{ hasOrders: boolean }>(`/accounts/${buyer.personId}`)
                expect(account.body.hasOrders).toBe(true)
            })

        it("an expired session is refused at the order boundary until a fresh sign-in resumes it",
            async () => {
                const identity = http.client("identity")
                const order = http.client("order")
                const buyer = await registerBuyer(auth,
                    "xsrv-b",
                    password)
                personIds.push(buyer.personId)
                const expired = bearer(buyer.sessionToken)

                // Live while the TTL holds.
                const live = await order.get<CartView>("/cart",
                    expired)
                expect(live.status).toBe(200)

                // The Redis TTL kills the session in the store itself - wait for the honest expiry rather
                // than simulating one.
                await retryUntil("identity session expiry (IDENTITY_SESSION_TTL_SECONDS=10)",
                    45_000,
                    async () => {
                        const probe = await identity.post<RefusalView>("/sessions/verify",
                            {
                                sessionToken: buyer.sessionToken 
                            })
                        return probe.status === 401
                    })

                const refused = await order.get<RefusalView>("/cart",
                    expired)
                expect(refused.status).toBe(401)
                expect(refused.body.code).toBe("SESSION_INVALID")

                // A fresh sign-in issues a new token for the same person and the journey resumes.
                const resumed = await auth.signIn(buyer.email,
                    password)
                expect(resumed.personId).toBe(buyer.personId)
                expect(resumed.sessionToken).not.toBe(buyer.sessionToken)
                const resumedCart = await order.get<CartView>("/cart",
                    bearer(resumed.sessionToken))
                expect(resumedCart.status).toBe(200)
            })
    })

import {
    E2EAuthService, E2ESession 
} from "@tests/infra"

/** Shared view types for the order-lifecycle lane: the response shapes the public doors answer with. */
export interface ProductView {
  id: string;
  name: string;
  priceMinorUnits: number;
  stock: number;
}

export interface CartView {
  items: Array<{ productId: string; quantity: number }>;
  catalog: Array<ProductView>;
}

export interface PlaceOrderView {
  orderId: string;
  status: "confirmed";
  totalMinorUnits: number;
  currency: "USD";
  paymentId: string;
  replayed: boolean;
}

/** The named-refusal body every checkout door can answer (401 SESSION_INVALID, 4xx CHECKOUT_REFUSED). */
export interface RefusalView {
  code?: string;
  reason?: string;
  productId?: string;
}

export interface CountRow {
  count: number;
}

export const bearer = (sessionToken: string): Record<string, string> => ({
    authorization: `Bearer ${sessionToken}`,
})

/** A fresh person per journey: unique email, registered and signed in through the public doors. */
export async function registerBuyer(auth: E2EAuthService, tag: string, password: string): Promise<E2ESession> {
    const email = `e2e-${tag}-${Date.now()}-${Math.random().toString(36).slice(2,
        8)}@ecommerce.dev`
    await auth.register(email,
        password)
    return auth.signIn(email,
        password)
}

import {
    Test, TestingModule 
} from "@nestjs/testing"
import {
    E2EAuthService,
    E2EDbService,
    E2EHttpService,
    E2EStackService,
    TestContext,
    TestingInfraModule,
} from "@tests/infra"
import {
    bearer,
    CartView,
    CountRow,
    PlaceOrderView,
    ProductView,
    RefusalView,
    registerBuyer,
} from "./lifecycle.helpers"

interface OrderRow {
  id: string;
  status: string;
  total_minor_units: number;
  currency: string;
  idempotency_key: string | null;
}

interface OrderLineRow {
  product_id: string;
  quantity: number;
  unit_price_minor_units: number;
}

interface PaymentRow {
  id: string;
  order_id: string;
  status: string;
  amount_minor_units: number;
  idempotency_key: string;
}

/**
 * The order lifecycle past the first confirmation: one buyer places several orders and the
 * history those orders produce is verified end to end. This api has no order list/detail door
 * at all - the only order reads are the POST /orders answer itself and the hasOrders flag order
 * serves identity on GET /buyers/:personId (contract.checkout.order-for-identity). So "list"
 * and "detail" are asserted where the truth lives: out-of-band on this run's postgres volume
 * (sales_order / sales_order_line / payment rows), cross-checked against the live cross-service
 * reads. The "status transitions" the schema actually models are covered too: a confirmation
 * lands 'confirmed' with its payment 'captured', a refusal appends nothing, and an
 * Idempotency-Key replay returns the first answer without appending either.
 *
 * Run: npx jest --config test/e2e/jest.config.js test/e2e/order-lifecycle/order-history.e2e-spec.ts
 */
describe("order lifecycle - order history (e2e)",
    () => {
        let moduleRef: TestingModule
        let stack: E2EStackService
        let auth: E2EAuthService
        let db: E2EDbService
        let http: E2EHttpService

        const password = "e2e-history-pass"
        const personIds: Array<string> = []

        beforeAll(async () => {
            moduleRef = await Test.createTestingModule({
                imports: [TestingInfraModule.register({
                    context: TestContext.E2E, specId: "order-lifecycle/order-history" 
                })],
            }).compile()
            // compile() only instantiates; init() runs the onModuleInit hook that brings the stack up.
            await moduleRef.init()
            stack = moduleRef.get(E2EStackService)
            auth = moduleRef.get(E2EAuthService)
            db = moduleRef.get(E2EDbService)
            http = moduleRef.get(E2EHttpService)
        },
        300_000)

        afterAll(async () => {
            for (const personId of personIds) await auth.deleteAccount(personId)
            await moduleRef.close()
            // Teardown verification is part of the contract: this run's containers and volumes are gone.
            expect(stack.cleanupReport).not.toBeNull()
            expect(stack.cleanupReport?.clean).toBe(true)
        })

        async function orderCount(personId: string): Promise<number> {
            const rows = await db.query<CountRow>("select count(*)::int as count from sales_order where person_id = $1",
                [personId])
            return rows[0].count
        }

        it("a buyer placing several orders builds a confirmed, paid history both services can read",
            async () => {
                const identity = http.client("identity")
                const order = http.client("order")
                const buyer = await registerBuyer(auth,
                    "hist-a",
                    password)
                personIds.push(buyer.personId)
                const authz = bearer(buyer.sessionToken)

                // Baseline: not a buyer yet - on both sides of the contract.
                const freshBuyer = await order.get<{ personId: string; hasOrders: boolean }>(`/buyers/${buyer.personId}`)
                expect(freshBuyer.body).toEqual({
                    personId: buyer.personId, hasOrders: false 
                })
                const freshAccount = await identity.get<{ hasOrders: boolean }>(`/accounts/${buyer.personId}`)
                expect(freshAccount.body.hasOrders).toBe(false)

                // The catalog snapshot the confirmations will price against (the cart door is the only
                // catalog surface checkout has).
                const browsed = await order.get<CartView>("/cart",
                    authz)
                expect(browsed.status).toBe(200)
                const catalog = new Map<string, ProductView>(browsed.body.catalog.map((p) => [p.id,
                    p]))
                const mug = catalog.get("sku-mug")!
                const notebook = catalog.get("sku-notebook")!
                const thermos = catalog.get("sku-thermos")!
                const firstTotal = mug.priceMinorUnits * 2
                const secondTotal = notebook.priceMinorUnits + thermos.priceMinorUnits

                // Order 1: sku-mug x2.
                const addedMug = await order.post("/cart/items",
                    {
                        productId: "sku-mug", quantity: 2 
                    },
                    authz)
                expect(addedMug.status).toBe(201)
                const first = await order.post<PlaceOrderView>("/orders",
                    undefined,
                    {
                        ...authz, "idempotency-key": `${buyer.personId}-1` 
                    })
                expect(first.status).toBe(201)
                expect(first.body).toMatchObject({
                    status: "confirmed", totalMinorUnits: firstTotal, currency: "USD", replayed: false 
                })

                // The cart cleared itself at confirmation, so order 2 starts from a fresh fill.
                const emptied = await order.get<CartView>("/cart",
                    authz)
                expect(emptied.body.items).toEqual([])

                // Order 2: sku-notebook x1 + sku-thermos x1.
                await order.post("/cart/items",
                    {
                        productId: "sku-notebook", quantity: 1 
                    },
                    authz)
                await order.post("/cart/items",
                    {
                        productId: "sku-thermos", quantity: 1 
                    },
                    authz)
                const second = await order.post<PlaceOrderView>("/orders",
                    undefined,
                    {
                        ...authz, "idempotency-key": `${buyer.personId}-2` 
                    })
                expect(second.status).toBe(201)
                expect(second.body).toMatchObject({
                    status: "confirmed", totalMinorUnits: secondTotal, replayed: false 
                })
                expect(second.body.orderId).not.toBe(first.body.orderId)
                expect(second.body.paymentId).not.toBe(first.body.paymentId)

                // list: two orders in creation order, each confirmed and priced as answered.
                const orders = await db.query<OrderRow>(
                    "select id, status, total_minor_units, currency, idempotency_key from sales_order where person_id = $1 order by created_at, id",
                    [buyer.personId],
                )
                expect(orders).toHaveLength(2)
                expect(orders[0]).toMatchObject({
                    id: first.body.orderId,
                    status: "confirmed",
                    total_minor_units: firstTotal,
                    currency: "USD",
                    idempotency_key: `${buyer.personId}-1`,
                })
                expect(orders[1]).toMatchObject({
                    id: second.body.orderId,
                    status: "confirmed",
                    total_minor_units: secondTotal,
                    idempotency_key: `${buyer.personId}-2`,
                })

                // detail: each order's lines carry the catalog price snapshot taken at confirmation.
                const firstLines = await db.query<OrderLineRow>(
                    "select product_id, quantity, unit_price_minor_units from sales_order_line where order_id = $1 order by product_id",
                    [first.body.orderId],
                )
                expect(firstLines).toEqual([{
                    product_id: "sku-mug", quantity: 2, unit_price_minor_units: mug.priceMinorUnits 
                }])
                const secondLines = await db.query<OrderLineRow>(
                    "select product_id, quantity, unit_price_minor_units from sales_order_line where order_id = $1 order by product_id",
                    [second.body.orderId],
                )
                expect(secondLines).toEqual([
                    {
                        product_id: "sku-notebook", quantity: 1, unit_price_minor_units: notebook.priceMinorUnits 
                    },
                    {
                        product_id: "sku-thermos", quantity: 1, unit_price_minor_units: thermos.priceMinorUnits 
                    },
                ])

                // ...and each order has exactly one captured payment, keyed by the order id.
                const payments = await db.query<PaymentRow>(
                    "select id, order_id, status, amount_minor_units, idempotency_key from payment where person_id = $1 order by created_at, id",
                    [buyer.personId],
                )
                expect(payments).toHaveLength(2)
                expect(payments[0]).toMatchObject({
                    id: first.body.paymentId,
                    order_id: first.body.orderId,
                    status: "captured",
                    amount_minor_units: firstTotal,
                    idempotency_key: first.body.orderId,
                })
                expect(payments[1]).toMatchObject({
                    id: second.body.paymentId,
                    order_id: second.body.orderId,
                    status: "captured",
                    amount_minor_units: secondTotal,
                    idempotency_key: second.body.orderId,
                })

                // The guarded stock moved by exactly the confirmed quantities, and the cart stayed empty.
                const after = await order.get<CartView>("/cart",
                    authz)
                const afterCatalog = new Map<string, ProductView>(after.body.catalog.map((p) => [p.id,
                    p]))
                expect(afterCatalog.get("sku-mug")!.stock).toBe(mug.stock - 2)
                expect(afterCatalog.get("sku-notebook")!.stock).toBe(notebook.stock - 1)
                expect(afterCatalog.get("sku-thermos")!.stock).toBe(thermos.stock - 1)
                expect(after.body.items).toEqual([])

                // The cross-service read: identity can only know this by asking order over real HTTP.
                const buyerNow = await order.get<{ personId: string; hasOrders: boolean }>(`/buyers/${buyer.personId}`)
                expect(buyerNow.body).toEqual({
                    personId: buyer.personId, hasOrders: true 
                })
                const accountNow = await identity.get<{ personId: string; email: string; hasOrders: boolean }>(`/accounts/${buyer.personId}`)
                expect(accountNow.body).toMatchObject({
                    personId: buyer.personId, email: buyer.email, hasOrders: true 
                })
            })

        it("a refusal and an idempotent replay never append to order history",
            async () => {
                const order = http.client("order")
                const buyer = await registerBuyer(auth,
                    "hist-b",
                    password)
                personIds.push(buyer.personId)
                const authz = bearer(buyer.sessionToken)

                // Refusal 1: an empty cart confirms nothing and records nothing.
                const emptyRefusal = await order.post<RefusalView>("/orders",
                    undefined,
                    authz)
                expect(emptyRefusal.status).toBe(400)
                expect(emptyRefusal.body).toMatchObject({
                    code: "CHECKOUT_REFUSED", reason: "cart-empty" 
                })
                expect(await orderCount(buyer.personId)).toBe(0)

                // A real order, then the same key again: the key is checked before the (now empty) cart, so
                // the replay returns the first answer rather than degenerating into a cart-empty refusal.
                await order.post("/cart/items",
                    {
                        productId: "sku-mug", quantity: 1 
                    },
                    authz)
                const key = `${buyer.personId}-replay`
                const placed = await order.post<PlaceOrderView>("/orders",
                    undefined,
                    {
                        ...authz, "idempotency-key": key 
                    })
                expect(placed.status).toBe(201)
                expect(placed.body.replayed).toBe(false)

                const replayed = await order.post<PlaceOrderView>("/orders",
                    undefined,
                    {
                        ...authz, "idempotency-key": key 
                    })
                expect(replayed.status).toBe(201)
                expect(replayed.body).toMatchObject({
                    orderId: placed.body.orderId,
                    paymentId: placed.body.paymentId,
                    replayed: true,
                })
                expect(await orderCount(buyer.personId)).toBe(1)
                const payments = await db.query<CountRow>("select count(*)::int as count from payment where person_id = $1",
                    [buyer.personId])
                expect(payments[0].count).toBe(1)

                // Refusal 2: beyond stock. Nothing changes - order count stays 1, the cart keeps its line,
                // and the catalog's stock did not move.
                const browsed = await order.get<CartView>("/cart",
                    authz)
                const thermos = browsed.body.catalog.find((p) => p.id === "sku-thermos")!
                await order.post("/cart/items",
                    {
                        productId: "sku-thermos", quantity: thermos.stock + 1 
                    },
                    authz)
                const stockRefusal = await order.post<RefusalView>("/orders",
                    undefined,
                    authz)
                expect(stockRefusal.status).toBe(409)
                expect(stockRefusal.body).toMatchObject({
                    code: "CHECKOUT_REFUSED", reason: "insufficient-stock", productId: "sku-thermos" 
                })
                expect(await orderCount(buyer.personId)).toBe(1)
                const keptCart = await order.get<CartView>("/cart",
                    authz)
                expect(keptCart.body.items).toEqual([{
                    productId: "sku-thermos", quantity: thermos.stock + 1 
                }])
                expect(keptCart.body.catalog.find((p) => p.id === "sku-thermos")!.stock).toBe(thermos.stock)
            })
    })

/**
 * Lane E2E-09 contract adapter + docker observation helpers.
 *
 * These specs are written against the frozen E2E-00/E2E-06 infra contract (ex-testing/ANALYSIS.md
 * §5): `TestingInfraModule.register({context})` as the spec's only import, `E2EStackService` owning
 * compose up on module init and `down -v` on shutdown. The infra modules are loaded dynamically so
 * the specs skip with an explicit reason while the owning lanes have not landed them, instead of
 * failing module resolution. Contract lookups are deliberately duck-typed (deep-scan for the live
 * compose project name, probe discovered loopback URLs for /health) so property-name choices in the
 * infra implementation do not break these specs.
 */
import {
    execFileSync 
} from "node:child_process"
import * as path from "node:path"

/* eslint-disable @typescript-eslint/no-explicit-any */

export interface E2EInfra {
  Test: any;
  TestingInfraModule: any;
  TestContext: any;
  E2EStackService: any;
}

export interface InfraLoad {
  infra: E2EInfra | null;
  reason: string | null;
}

export function loadInfra(e2eDir: string): InfraLoad {
    let Test: any
    try {
        Test = require("@nestjs/testing").Test
    } catch (e) {
        return {
            infra: null, reason: `@nestjs/testing not resolvable: ${(e as Error).message}` 
        }
    }
    // v2 layout: the module tree lives at src/tests/infra (a sibling of e2e/), with index.ts as the
    // spec-facing barrel re-exporting every public service and the options contract.
    const infraDir = path.join(e2eDir,
        "..",
        "infra")
    try {
        const barrel = require(path.join(infraDir,
            "index"))
        if (!barrel?.TestingInfraModule) {
            return {
                infra: null, reason: "infra/index does not export TestingInfraModule" 
            }
        }
        if (!barrel?.E2EStackService) {
            return {
                infra: null, reason: "infra/index does not export E2EStackService" 
            }
        }
        return {
            infra: {
                Test,
                TestingInfraModule: barrel.TestingInfraModule,
                TestContext: barrel.TestContext,
                E2EStackService: barrel.E2EStackService,
            },
            reason: null,
        }
    } catch (e) {
        return {
            infra: null, reason: `e2e infra module not loadable (E2E-00/E2E-06 contract pending): ${(e as Error).message}` 
        }
    }
}

/** Boots the contract module and returns the testing module ref plus the stack service instance. */
export async function bootE2EModule(infra: E2EInfra, specId?: string): Promise<{ moduleRef: any; stack: any }> {
    const moduleRef = await infra.Test.createTestingModule({
        imports: [infra.TestingInfraModule.register({
            context: infra.TestContext?.E2E ?? "e2e", specId 
        })],
    }).compile()
    await moduleRef.init()
    return {
        moduleRef, stack: moduleRef.get(infra.E2EStackService) 
    }
}

export function docker(args: Array<string>): string {
    return execFileSync("docker",
        args,
        {
            encoding: "utf8", maxBuffer: 16 * 1024 * 1024 
        }).trim()
}

export function dockerLines(args: Array<string>): Array<string> {
    const out = docker(args)
    return out ? out.split(/\r?\n/).map((line) => line.trim()).filter(Boolean) : []
}

export function dockerAvailable(): boolean {
    try {
        execFileSync("docker",
            ["version",
                "--format",
                "{{.Server.Version}}"],
            {
                stdio: "pipe", timeout: 20_000 
            })
        return true
    } catch {
        return false
    }
}

/** Every compose project label currently present on the daemon -- the ground truth the stack's own
 * project-name field is matched against, so no accessor-name guess is needed. */
function liveComposeProjects(): Set<string> {
    const labels = dockerLines(["ps",
        "-a",
        "--format",
        "{{.Label \"com.docker.compose.project\"}}"])
    return new Set(labels.filter(Boolean))
}

/** Finds the run-scoped compose project name wherever the stack service stores it. */
export function composeProjectOf(stack: unknown): string | null {
    const live = liveComposeProjects()
    let found: string | null = null
    const scan = (value: any, depth: number): void => {
        if (found !== null || value === null || value === undefined || depth < 0) return
        if (typeof value === "string") {
            if (live.has(value)) found = value
            return
        }
        if (typeof value === "object") {
            for (const key of Object.keys(value)) scan(value[key],
                depth - 1)
        }
    }
    scan(stack,
        5)
    return found
}

/** All loopback http(s) URLs stored anywhere on the stack object (baseUrl fields, per-service urls). */
export function loopbackUrlsOf(stack: unknown): Array<string> {
    const urls = new Set<string>()
    const scan = (value: any, depth: number): void => {
        if (value === null || value === undefined || depth < 0) return
        if (typeof value === "string") {
            if (/^https?:\/\/(127\.0\.0\.1|localhost)(:\d+)?/.test(value)) urls.add(value.replace(/\/+$/,
                ""))
            return
        }
        if (typeof value === "object") {
            for (const key of Object.keys(value)) scan(value[key],
                depth - 1)
        }
    }
    scan(stack,
        5)
    return [...urls]
}

export async function httpStatus(url: string, timeoutMs = 5_000): Promise<number | null> {
    try {
        const response = await fetch(url,
            {
                signal: AbortSignal.timeout(timeoutMs) 
            })
        await response.arrayBuffer().catch(() => undefined)
        return response.status
    } catch {
        return null
    }
}

/** The subset of discovered URLs answering `GET /health` with `{status:'ok'}` -- the api doors only. */
export async function apiHealthUrls(stack: unknown): Promise<Array<string>> {
    const apis: Array<string> = []
    for (const base of loopbackUrlsOf(stack)) {
        try {
            const response = await fetch(`${base}/health`,
                {
                    signal: AbortSignal.timeout(4_000) 
                })
            if (response.status !== 200) continue
            const body = (await response.json()) as { status?: string }
            if (body?.status === "ok") apis.push(base)
        } catch {
            // Not an api door -- ignore.
        }
    }
    return apis
}

/** Compose service names this run actually has containers for -- from docker labels, so the spec
 * never hardcodes the stack's spelling or needs the compose file's run-scoped env vars. */
export function projectServices(project: string): Array<string> {
    const labels = dockerLines([
        "ps",
        "-a",
        "--filter",
        `label=com.docker.compose.project=${project}`,
        "--format",
        "{{.Label \"com.docker.compose.service\"}}",
    ])
    return [...new Set(labels.filter(Boolean))]
}

/** Container id of one compose service inside the run's project. */
export function projectContainer(project: string, service: string): string | null {
    return (
        dockerLines([
            "ps",
            "-a",
            "--filter",
            `label=com.docker.compose.project=${project}`,
            "--filter",
            `label=com.docker.compose.service=${service}`,
            "--format",
            "{{.ID}}",
        ])[0] ?? null
    )
}

/**
 * Kill and later restart one service container with plain docker. Deliberately not
 * `docker compose kill/up`: those re-interpolate the compose file and this spec does not own the
 * run-scoped env (ports, credentials) the stack service expanded at boot time. `docker start` puts
 * back the identical container - same published ports, same volumes.
 */
export function killService(project: string, servicePattern: RegExp): { service: string; id: string } {
    const service = projectServices(project).find((name) => servicePattern.test(name))
    if (!service) throw new Error(`no service matching ${servicePattern} in project ${project}`)
    const id = projectContainer(project,
        service)
    if (!id) throw new Error(`no container for service ${service} in project ${project}`)
    docker(["kill",
        id])
    return {
        service, id 
    }
}

export function startContainer(id: string): void {
    docker(["start",
        id])
}

export async function retryUntil(
    label: string,
    timeoutMs: number,
    probe: () => Promise<boolean>,
    intervalMs = 1_000,
): Promise<void> {
    const deadline = Date.now() + timeoutMs
    let last: unknown
    while (Date.now() < deadline) {
        try {
            if (await probe()) return
        } catch (e) {
            last = e
        }
        await new Promise((resolve) => setTimeout(resolve,
            intervalMs))
    }
    throw new Error(`timed out waiting for ${label}${last ? ` (last error: ${last})` : ""}`)
}

/**
 * Lane E2E-09 -- infra-down recovery (ecommerce-app-be).
 *
 * Boots the run-scoped stack, kills the redis container mid-run, asserts both apis stay alive and
 * answer /health with a clean 503 (identity reports checks.redis unreachable; order cascades through
 * identity's health), starts the same container back, and asserts every api door recovers to 200.
 * Written against the frozen E2E-06 contract (ex-testing/ANALYSIS.md §5); skips with a reason while
 * that infra has not landed.
 */
import * as path from "node:path"
import {
    apiHealthUrls,
    bootE2EModule,
    composeProjectOf,
    dockerAvailable,
    httpStatus,
    killService,
    loadInfra,
    retryUntil,
    startContainer,
} from "./e2e-infra-contract"

const E2E_DIR = path.resolve(__dirname,
    "..")
const { infra, reason } = loadInfra(E2E_DIR)
const runnable = infra !== null && dockerAvailable()
if (!runnable) {
    console.warn(`[e2e-09] infra-recovery skipped: ${reason ?? "docker daemon not reachable"}`)
}
const describeE2E = runnable ? describe : describe.skip

describeE2E("resilience: infra recovery",
    () => {
        jest.setTimeout(600_000)

        it("redis outage yields clean api errors and both apis recover when redis returns",
            async () => {
                const { moduleRef, stack } = await bootE2EModule(infra!,
                    "resilience/infra-recovery")
                try {
                    const project = composeProjectOf(stack)
                    expect(project).not.toBeNull()

                    const apis = await apiHealthUrls(stack)
                    expect(apis.length).toBeGreaterThan(0)

                    const killed = killService(project!,
                        /redis/i)

                    // Both apis tolerate the outage: still answering HTTP with a declared dependency error.
                    for (const base of apis) {
                        await retryUntil(`${base}/health answers 503`,
                            90_000,
                            async () => (await httpStatus(`${base}/health`,
                                15_000)) === 503)
                    }

                    startContainer(killed.id)

                    for (const base of apis) {
                        await retryUntil(`${base}/health recovers to 200`,
                            180_000,
                            async () => (await httpStatus(`${base}/health`)) === 200)
                    }
                } finally {
                    await moduleRef.close().catch(() => undefined)
                }
            })
    })

/**
 * Lane E2E-09 -- teardown contract verification (ecommerce-app-be).
 *
 * Boots the run-scoped stack through TestingInfraModule, records the exact containers and volumes
 * this run created, closes the module (the same path every spec's afterAll takes), then proves by
 * direct docker observation that none of them remain -- the contract E2EStackService implements in
 * onApplicationShutdown (`down -v` + cleanup verification). Written against the frozen E2E-06
 * contract (ex-testing/ANALYSIS.md §5); skips with a reason while that infra has not landed.
 */
import * as path from "node:path"
import {
    bootE2EModule,
    composeProjectOf,
    dockerAvailable,
    dockerLines,
    loadInfra,
} from "./e2e-infra-contract"

const E2E_DIR = path.resolve(__dirname,
    "..")
const { infra, reason } = loadInfra(E2E_DIR)
const runnable = infra !== null && dockerAvailable()
if (!runnable) {
    console.warn(`[e2e-09] teardown-verification skipped: ${reason ?? "docker daemon not reachable"}`)
}
const describeE2E = runnable ? describe : describe.skip

describeE2E("resilience: teardown verification",
    () => {
        jest.setTimeout(600_000) // first-boot images + two api processes can take minutes

        it("closing the module removes every container and volume the run created",
            async () => {
                const { moduleRef, stack } = await bootE2EModule(infra!,
                    "resilience/teardown-verification")
                let closed = false
                try {
                    const project = composeProjectOf(stack)
                    expect(project).not.toBeNull() // stack must expose its run-scoped compose project name

                    const containers = dockerLines([
                        "ps",
                        "-a",
                        "--filter",
                        `label=com.docker.compose.project=${project}`,
                        "--format",
                        "{{.Names}}",
                    ])
                    const volumes = dockerLines([
                        "volume",
                        "ls",
                        "--filter",
                        `name=${project}`,
                        "--format",
                        "{{.Name}}",
                    ])
                    expect(containers.length).toBeGreaterThan(0)

                    await moduleRef.close()
                    closed = true

                    // The contract: after module close, nothing of this run's project survives on the daemon.
                    expect(
                        dockerLines(["ps",
                            "-a",
                            "--filter",
                            `label=com.docker.compose.project=${project}`,
                            "--format",
                            "{{.Names}}"]),
                    ).toEqual([])
                    expect(
                        dockerLines(["volume",
                            "ls",
                            "--filter",
                            `name=${project}`,
                            "--format",
                            "{{.Name}}"]),
                    ).toEqual([])

                    for (const name of containers) {
                        expect(() => dockerLines(["container",
                            "inspect",
                            name])).toThrow()
                    }
                    for (const name of volumes) {
                        expect(() => dockerLines(["volume",
                            "inspect",
                            name])).toThrow()
                    }

                    // The stack's own teardown self-report, if the implementation exposes one, must agree.
                    const report = stack.teardownReport ?? stack.cleanupReport
                    if (report !== null && report !== undefined) {
                        expect(report.clean).toBe(true)
                    }
                } finally {
                    if (!closed) await moduleRef.close().catch(() => undefined)
                }
            })
    })

