export interface E2EAccount {
  personId: string;
  email: string;
}

export interface E2ESession extends E2EAccount {
  sessionToken: string;
}

/**
 * Test-account lifecycle for the suite. Accounts are created through the identity service's own
 * public register door (there is no external IdP in this stack - the person IS the identity_person
 * row); deletion is out-of-band through the db service, so a spec can guarantee its rows are gone
 * without relying on a delete endpoint the product does not expose.
 */
@Injectable()
export class E2EAuthService {
    constructor(
    private readonly http: E2EHttpService,
    private readonly db: E2EDbService,
    ) {}

    async register(email: string, password: string): Promise<E2EAccount> {
        const response = await this.http.client("identity").post<{ personId?: string }>("/auth/register",
            {
                email, password 
            })
        if (response.status !== 201 || !response.body?.personId) {
            throw new Error(`register for ${email} failed: ${response.status} ${JSON.stringify(response.body).slice(0,
                300)}`)
        }
        return {
            personId: response.body.personId, email 
        }
    }

    async signIn(email: string, password: string): Promise<E2ESession> {
        const response = await this.http
            .client("identity")
            .post<{ sessionToken?: string; personId?: string }>("/auth/sign-in",
                {
                    email, password 
                })
        if (response.status !== 201 || !response.body?.sessionToken || !response.body.personId) {
            throw new Error(`sign-in for ${email} failed: ${response.status} ${JSON.stringify(response.body).slice(0,
                300)}`)
        }
        return {
            personId: response.body.personId, email, sessionToken: response.body.sessionToken 
        }
    }

    /** Out-of-band delete of the person row; sessions in redis die with the container anyway. */
    async deleteAccount(personId: string): Promise<void> {
        await this.db.query("delete from identity_person where id = $1",
            [personId])
    }
}

import {
    Injectable 
} from "@nestjs/common"
import axios, {
    AxiosInstance 
} from "axios"
import {
    E2EServiceName, E2EStackService 
} from "../../platform/stack/e2e-stack.service"

export interface E2EResponse<T = unknown> {
  status: number;
  body: T;
  /** Alias of `body` - specs read payloads as `data`; both names resolve to the same value. */
  data: T;
  durationMs: number;
}

export interface E2EHttpClientOptions {
  /** Bearer session token folded into every request this client sends. */
  bearerToken?: string;
}

export interface E2EHttpClient {
  get<T = unknown>(path: string, headers?: Record<string, string>): Promise<E2EResponse<T>>;
  post<T = unknown>(path: string, body?: unknown, headers?: Record<string, string>): Promise<E2EResponse<T>>;
  put<T = unknown>(path: string, body?: unknown, headers?: Record<string, string>): Promise<E2EResponse<T>>;
  patch<T = unknown>(path: string, body?: unknown, headers?: Record<string, string>): Promise<E2EResponse<T>>;
  delete<T = unknown>(path: string, headers?: Record<string, string>): Promise<E2EResponse<T>>;
  baseUrl: string;
}

/**
 * One axios instance per service/user, bound to the ports this run allocated. Nothing here knows a
 * port literal - base URLs come from the stack service, which got them from the OS. Every status is
 * data for a spec (a 401/409 refusal is asserted, never thrown), so validateStatus accepts all.
 */
@Injectable()
export class E2EHttpService {
    constructor(private readonly stack: E2EStackService) {}

    client(service: E2EServiceName, options: E2EHttpClientOptions = {
    }): E2EHttpClient {
        const { baseUrl } = this.stack.endpoint(service)
        const api: AxiosInstance = axios.create({
            baseURL: baseUrl,
            validateStatus: () => true,
            headers: options.bearerToken ? {
                authorization: `Bearer ${options.bearerToken}` 
            } : {
            },
        })
        const request = async <T>(method: string, path: string, body?: unknown, headers: Record<string, string> = {
        }): Promise<E2EResponse<T>> => {
            const startedAt = Date.now()
            const response = await api.request({
                method, url: path, data: body, headers 
            })
            const parsed = typeof response.data === "string" ? {
                unparsableBody: response.data.slice(0,
                    2000) 
            } : response.data
            return {
                status: response.status, body: parsed as T, data: parsed as T, durationMs: Date.now() - startedAt 
            }
        }
        return {
            baseUrl,
            get: <T>(path: string, headers?: Record<string, string>) => request<T>("GET",
                path,
                undefined,
                headers),
            post: <T>(path: string, body?: unknown, headers?: Record<string, string>) => request<T>("POST",
                path,
                body,
                headers),
            put: <T>(path: string, body?: unknown, headers?: Record<string, string>) => request<T>("PUT",
                path,
                body,
                headers),
            patch: <T>(path: string, body?: unknown, headers?: Record<string, string>) => request<T>("PATCH",
                path,
                body,
                headers),
            delete: <T>(path: string, headers?: Record<string, string>) => request<T>("DELETE",
                path,
                undefined,
                headers),
        }
    }
}

