/**
 * The checkout session door in wiring form: SessionGuard must be a CheckoutModule provider that
 * resolves with the identity integration client injected, must sit as the one class-level guard
 * on every person-scoped controller, and must be absent from the two intentionally open doors
 * (the contract.checkout.order-for-identity provider and /health). The canActivate assertions
 * prove the guard's refusal shape - the consumer-obligation doctrine that an unverifiable or
 * missing token is this service's own 401, never an invented actor.
 */
interface IdentityBoundary {
  verifySession: jest.Mock;
  isHealthy: jest.Mock;
}

function httpContext(request: Partial<Request & { actor?: ActorParams }>): ExecutionContext {
    return {
        switchToHttp: () => ({
            getRequest: () => request 
        }),
    } as unknown as ExecutionContext
}

async function expectSessionRefusal(guard: SessionGuard, context: ExecutionContext): Promise<void> {
    try {
        await guard.canActivate(context)
        throw new Error("the request should have been refused")
    } catch (error) {
        expect(error).toBeInstanceOf(HttpException)
        expect((error as HttpException).getStatus()).toBe(401)
        expect((error as HttpException).getResponse()).toMatchObject({
            code: "SESSION_INVALID" 
        })
    }
}

describe("checkout SessionGuard - wiring",
    () => {
        let module: TestingModule
        let guard: SessionGuard
        const identity: IdentityBoundary = {
            verifySession: jest.fn(), isHealthy: jest.fn() 
        }

        beforeAll(async () => {
            const dataSource = {
                isInitialized: false,
                entityMetadatas: [],
                options: {
                    type: "postgres" 
                },
                manager: {
                },
                getRepository: jest.fn(() => ({
                })),
                query: jest.fn(),
                destroy: jest.fn(),
            } as unknown as DataSource
            const config = {
                getProject: () => "ecommerce-app-be",
                getPort: () => 0,
                getDatabaseUrl: () => "postgres://postgres@localhost:0/ecommerce",
                getIdentityApiBaseUrl: () => "http://localhost:0",
            } as unknown as AppConfigService
            module = await Test.createTestingModule({
                imports: [ConfigModule,
                    CheckoutModule] 
            })
                .overrideProvider(getDataSourceToken(POSTGRESQL_PRIMARY))
                .useValue(dataSource)
            // forRootAsync's options carry no `name`, so shutdown would look up the default DataSource
            // token and throw; naming the options double keeps module.close() honest.
                .overrideProvider("TypeOrmModuleOptions")
                .useValue({
                    name: POSTGRESQL_PRIMARY, type: "postgres" 
                })
                .overrideProvider(AppConfigService)
                .useValue(config)
                .overrideProvider(IdentityApiClient)
                .useValue(identity)
                .compile()
            guard = module.get(SessionGuard)
        })

        afterAll(async () => {
            await module.close()
        })

        beforeEach(() => {
            jest.clearAllMocks()
        })

        it("resolves SessionGuard as a CheckoutModule provider with the identity client injected",
            () => {
                expect(guard).toBeInstanceOf(SessionGuard)
                expect((guard as unknown as { identityApi: IdentityBoundary }).identityApi).toBe(identity)
            })

        it("places exactly SessionGuard, in class position, on every person-scoped door",
            () => {
                for (const controller of [CartController,
                    OrderController]) {
                    const guards = Reflect.getMetadata(GUARDS_METADATA,
                        controller) as Array<unknown> | undefined
                    expect(guards).toEqual([SessionGuard])
                }
            })

        it("leaves the contract provider door and the health probe unguarded",
            () => {
                for (const controller of [BuyerController,
                    HealthController]) {
                    expect((Reflect.getMetadata(GUARDS_METADATA,
                        controller) as Array<unknown> | undefined) ?? []).toEqual([])
                }
            })

        it.each([{
            headers: {
            } 
        },
        {
            headers: {
                authorization: "Basic abc" 
            } 
        },
        {
            headers: {
                authorization: "Bearer " 
            } 
        }])(
            "refuses a request carrying no Bearer token %j before identity is called",
            async (request) => {
                await expectSessionRefusal(guard,
                    httpContext(request as Partial<Request & { actor?: ActorParams }>))
                expect(identity.verifySession).not.toHaveBeenCalled()
            },
        )

        it("admits a verified Bearer token and stamps the verified person on the request",
            async () => {
                identity.verifySession.mockResolvedValue({
                    personId: "person-9" 
                })
                const request = {
                    headers: {
                        authorization: "Bearer token-abc" 
                    } 
                } as Request & { actor?: ActorParams }
                await expect(guard.canActivate(httpContext(request))).resolves.toBe(true)
                expect(identity.verifySession).toHaveBeenCalledWith("token-abc")
                expect(request.actor).toEqual({
                    personId: "person-9" 
                })
            })

        it("refuses when identity answers that no live session owns the token",
            async () => {
                identity.verifySession.mockResolvedValue(null)
                const request = {
                    headers: {
                        authorization: "Bearer token-gone" 
                    } 
                } as Request & { actor?: ActorParams }
                await expectSessionRefusal(guard,
                    httpContext(request))
                expect(identity.verifySession).toHaveBeenCalledWith("token-gone")
                expect(request.actor).toBeUndefined()
            })
    })
